PREFIX ref: <https://example.com/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?point ?label ?ts ?class WHERE {
  ?point a brick:Electric_Power .
  OPTIONAL { ?point brick:hasSubEntity ?sub }
  ?point rdfs:label ?label .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
  OPTIONAL { ?point brick:hasProperty ?class }
}

